<?php session_start();require_once "config/database.php";header('Content-Type: application/json');if(!isset($_SESSION['user_id'])){http_response_code(401);echo json_encode(['error'=>'login']);exit;} $me=(int)$_SESSION['user_id'];$action=$_GET['action']??'';$other=(int)($_GET['user_id']??$_POST['user_id']??0);if(!$other||$other===$me){echo json_encode(['messages'=>[]]);exit;}if($action==='send'){ $m=trim($_POST['message']??''); if($m!==''){ $s=$pdo->prepare('INSERT INTO messages(sender_id,receiver_id,message) VALUES(?,?,?)');$s->execute([$me,$other,$m]); $pdo->prepare('INSERT INTO notifications(user_id,title,message,link) VALUES(?,?,?,?)')->execute([$other,'New message',$_SESSION['name'].' sent you a message','messages.php?user_id='.$me]); } echo json_encode(['ok'=>true]);exit;} $s=$pdo->prepare('SELECT id,sender_id,message,DATE_FORMAT(created_at,"%d %b %Y %h:%i %p") created_at FROM messages WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY created_at ASC');$s->execute([$me,$other,$other,$me]);echo json_encode(['messages'=>$s->fetchAll(PDO::FETCH_ASSOC)]);